//! The tenant domain model (the `tenants` table).

use chrono::{DateTime, Utc};
use uuid::Uuid;

/// One row of `tenants`: a party owning certificate authorities.
#[derive(Debug, Clone, PartialEq)]
pub struct Tenant {
    /// Primary key (uuid, generated by the database default).
    pub id: Uuid,
    /// Unique tenant name.
    pub name: String,
    /// Row creation time (database `now()` default).
    pub created_at: DateTime<Utc>,
}
